// Spike only. workerd worker for the jco-transpiled COMPONENT (Route D).
// jco's --instantiation async output asks for each core module by path;
// workerd hands over the precompiled modules as static imports, listed in
// modules.mjs (generated by scripts/workerd-parity.sh: one static import
// per aprv.core*.wasm).
import { modules } from './modules.mjs';
import { instantiate } from './aprv.js';
import { jsonl } from './driver.mjs';
import { makeJcoRunner } from './jco-driver.mjs';
import { wasiP2Min } from './wasi-p2-min.mjs';
import { WASI_P2 } from './policy.mjs';

const calls = {};
let runner = null;
export default {
  async fetch(request) {
    runner ||= makeJcoRunner(instantiate, (p) => modules[p], calls, WASI_P2 ? wasiP2Min(calls) : {});
    const run = await runner;
    const url = new URL(request.url);
    if (url.pathname === '/imports') {
      return Response.json({ imports: WebAssembly.Module.imports(modules['aprv.core.wasm']), calls });
    }
    const rows = jsonl(await request.text());
    const out = [];
    for (const r of rows) out.push(JSON.stringify(await run.run(r)));
    return new Response(out.join('\n') + '\n');
  },
};
